  public HotelFirearmKind kind;public Transform model;public Vector3 size,muzzleLocal,rightGripLocal,leftGripLocal;public float damage=28,interval=.24f,range=75,spread=.006f,reloadDuration=1.5f;public int capacity=12,reserveCapacity=72,pellets=1;public bool automatic,suppressed;
