  public void Configure(HotelFirearmKind type,Vector3 dimensions){kind=type;size=dimensions;automatic=kind==HotelFirearmKind.SMG||kind==HotelFirearmKind.Rifle;switch(kind){case HotelFirearmKind.SMG:damage=18;capacity=30;interval=.095f;spread=.012f;range=55;reloadDuration=1.85f;break;case HotelFirearmKind.Rifle:damage=30;capacity=30;interval=.12f;spread=.007f;range=100;reloadDuration=2.1f;break;case HotelFirearmKind.Sniper:damage=90;capacity=5;interval=.9f;spread=.001f;range=180;reloadDuration=2.4f;break;case HotelFirearmKind.Shotgun:damage=11;capacity=6;interval=.85f;spread=.065f;range=40;pellets=8;reloadDuration=3.1f;break;case HotelFirearmKind.Launcher:damage=120;capacity=1;interval=1.2f;spread=0;range=85;reloadDuration=2.9f;break;default:damage=28;capacity=12;interval=.24f;spread=.006f;range=75;reloadDuration=1.5f;break;}reserveCapacity=capacity*6;
   muzzleLocal=new Vector3(0,size.y*.25f,size.z*.49f);rightGripLocal=new Vector3(.025f,-size.y*.22f,-size.z*.14f);leftGripLocal=new Vector3(-.03f,-size.y*.05f,kind==HotelFirearmKind.Pistol?-size.z*.09f:size.z*.18f);ResetAmmo();}
