  bool CanAct(HotelPlayer p)=>isActiveAndEnabled&&p&&p.isActiveAndEnabled&&p.held&&p.held.gameObject==gameObject&&!p.GameplayPaused&&!p.transportLocked&&!p.seated&&!p.cart&&(!p.combat||!p.combat.IsDown);
  public bool BeginReload(HotelPlayer p){if(!CanAct(p)||Reloading||Ammo>=capacity||Reserve<=0)return false;user=p;Reloading=true;reloadTime=0;BuildEffects();sound.PlayOneShot(reloadClip,.45f);p.PlayGesture(HotelPlayerGesture.Reload,Muzzle);return true;}
