  public bool TryFire(HotelPlayer p){if(!CanAct(p)||Reloading||Time.time<nextShot)return false;user=p;BuildEffects();if(Ammo<=0){if(Time.time>=dryUntil){dryUntil=Time.time+.35f;sound.PlayOneShot(dryClip,.5f);}BeginReload(p);return false;}
   Ammo--;ShotsFired++;nextShot=Time.time+interval;recoilVelocity+=kind==HotelFirearmKind.Shotgun||kind==HotelFirearmKind.Launcher?9:kind==HotelFirearmKind.Sniper?7:4;recoil=Mathf.Min(1,recoil+.16f);flashUntil=Time.time+(suppressed?.025f:.055f);sound.pitch=(kind==HotelFirearmKind.Pistol?1.15f:kind==HotelFirearmKind.SMG?1.3f:kind==HotelFirearmKind.Sniper?.8f:kind==HotelFirearmKind.Launcher?.65f:1)*Random.Range(.96f,1.04f);sound.PlayOneShot(shotClip,suppressed?.3f:.8f);if(shells&&kind!=HotelFirearmKind.Launcher)shells.Emit(1);p.PlayGesture(HotelPlayerGesture.Fire,Muzzle);
   for(int i=0;i<pellets;i++){var disk=Random.insideUnitCircle*spread;var aim=(p.view.transform.forward+p.view.transform.right*disk.x+p.view.transform.up*disk.y).normalized;var origin=p.view.transform.position;var target=origin+aim*range;if(FindHit(origin,aim,range,out var eyeHit))target=eyeHit.point;var muzzle=Muzzle;if(Physics.CheckSphere(muzzle,.015f,~((1<<8)|(1<<9)),QueryTriggerInteraction.Ignore)){Impact(muzzle,-aim,false);break;}var touch=FindMuzzleTarget(muzzle);if(touch&&(!eyeHit.collider||eyeHit.distance>Vector3.Distance(origin,muzzle)||Target(eyeHit.collider)==Target(touch))){if(kind==HotelFirearmKind.Launcher){HotelRocketProjectile.Launch(this,p,muzzle,aim).Explode();break;}bool didKill;bool hurt=ApplyHit(touch,damage,origin,muzzle,aim,out didKill);if(hurt){hitUntil=Time.time+.2f;killed|=didKill;}Trace(i,muzzle,muzzle+aim*.02f);Impact(muzzle,-aim,hurt);continue;}var travel=target-muzzle;RaycastHit contact;bool blocked=FindHit(muzzle,travel.normalized,Mathf.Min(range,travel.magnitude)+.03f,out contact);var endpoint=blocked?contact.point:target;
