    Trace(i,muzzle,endpoint);if(blocked){float falloff=Mathf.Lerp(1,.55f,Mathf.Clamp01(contact.distance/range));bool didKill;bool hurt=ApplyHit(contact.collider,damage*falloff,origin,contact.point,aim,out didKill);if(hurt){hitUntil=Time.time+.2f;killed|=didKill;}Impact(contact.point,contact.normal,hurt);}
