  Collider FindMuzzleTarget(Vector3 point){int count=Physics.OverlapSphereNonAlloc(point,.012f,muzzleContacts,~((1<<8)|(1<<9)),QueryTriggerInteraction.Collide);for(int i=0;i<count;i++){var c=muzzleContacts[i];if(Target(c)&&(c.ClosestPoint(point)-point).sqrMagnitude<.0002f)return c;}return null;}
  public bool FindHit(Vector3 origin,Vector3 direction,float distance,out RaycastHit nearest){nearest=default;float best=distance+.001f;int count=Physics.RaycastNonAlloc(origin,direction,hits,distance,~((1<<8)|(1<<9)),QueryTriggerInteraction.Collide);var candidates=count==hits.Length?Physics.RaycastAll(origin,direction,distance,~((1<<8)|(1<<9)),QueryTriggerInteraction.Collide):hits;if(candidates!=hits)count=candidates.Length;for(int i=0;i<count;i++){var h=candidates[i];if(h.transform.IsChildOf(transform)||h.collider.isTrigger&&!Target(h.collider))continue;if(h.distance<best){best=h.distance;nearest=h;}}return nearest.collider;}
  public static Object Target(Collider c){var part=c.GetComponent<HotelGuestPhysicsPart>();if(part&&part.owner)return part.owner.GetComponent<HotelHuman>();var h=c.GetComponentInParent<HotelHuman>();if(h&&h.Guest)return h;return c.GetComponentInParent<HotelZombieBot>();}
  public static bool ApplyHit(Collider c,float amount,Vector3 source,Vector3 point,Vector3 direction,out bool dead){dead=false;if(!c)return false;var target=Target(c);if(target is HotelHuman h){if(h.Dead)return false;bool head=h.Guest&&h.Guest.PrankPhysics&&Vector3.Distance(point,h.Guest.PrankPhysics.HeadPoint)<.25f;bool applied=h.TakeBullet(amount*(head?1.75f:1),source,point);dead=h.Dead;return applied;}if(target is HotelZombieBot z){if(!z.Alive)return false;float before=z.Health;bool head=z.visual&&Vector3.Distance(point,z.visual.head.position)<.25f;z.Damage(amount*(head?1.75f:1),direction);dead=!z.Alive;return z.Health<before;}return false;}
  public void NotifyRocketHit(bool didKill){hitUntil=Time.time+.25f;killed|=didKill;}
  public void Impact(Vector3 point,Vector3 normal,bool target){BuildEffects();impacts.transform.position=point+normal*.015f;impacts.transform.rotation=Quaternion.LookRotation(normal);var main=impacts.main;main.startColor=target?new Color(.6f,.6f,.55f):new Color(1,.66f,.18f);impacts.Emit(target?5:9);}
  public void Advance(float dt){if(dt<=0)return;if(Reloading){if(!CanAct(user)){if(!user||!user.held||user.held.gameObject!=gameObject){Reloading=false;reloadTime=0;}return;}reloadTime+=dt;if(reloadTime>=reloadDuration){int count=Mathf.Min(capacity-Ammo,Reserve);Ammo+=count;Reserve-=count;Reloading=false;reloadTime=0;}}recoilVelocity-=recoil*120*dt;recoilVelocity*=Mathf.Exp(-14*dt);recoil=Mathf.Clamp(recoil+recoilVelocity*dt,0,1);}
  void Update(){Advance(Time.deltaTime);}
  void LateUpdate(){if(Time.deltaTime<=0)return;bool equipped=user&&user.held&&user.held.gameObject==gameObject;if(model){float r=equipped?ReloadProgress:0;float tilt=Mathf.Sin(r*Mathf.PI);model.localPosition=modelHome+new Vector3(0,-.08f*tilt,-.035f*recoil-.05f*tilt);model.localRotation=modelRotation*Quaternion.Euler(-9*recoil+18*tilt,0,-32*tilt);}
   if(flash){flash.SetActive(equipped&&Time.time<flashUntil);flash.transform.position=Muzzle;flash.transform.rotation=model?model.rotation:transform.rotation;if(flash.activeSelf)flash.transform.Rotate(0,0,Random.Range(0,180));}
   if(traces!=null)for(int i=0;i<traces.Length;i++)traces[i].enabled=Time.time<traceUntil[i];if(Time.time>hitUntil)killed=false;
  }
  public bool HandPose(float side,out Vector3 point,out Quaternion rotation,out float curl){point=Vector3.zero;rotation=Quaternion.identity;curl=.82f;if(!model)return false;var local=side<0?leftGripLocal:rightGripLocal;if(side<0&&Reloading){float p=ReloadProgress;float down=Mathf.Sin(Mathf.Clamp01(p/.75f)*Mathf.PI);local=Vector3.Lerp(leftGripLocal,rightGripLocal+new Vector3(-.08f,-.25f,-.12f),down);if(p>.8f)local=Vector3.Lerp(leftGripLocal,muzzleLocal*.5f,Mathf.Sin((p-.8f)/.2f*Mathf.PI));curl=.6f;}point=model.TransformPoint(local);rotation=model.rotation*Quaternion.Euler(65,side*12,side<0?-10:0);return true;}
  AudioClip Clip(string name,float duration,int type){int rate=24000;var clip=AudioClip.Create(name,(int)(rate*duration),1,rate,false);var samples=new float[(int)(rate*duration)];var rng=new System.Random(717+type);for(int i=0;i<samples.Length;i++){float t=i/(float)rate;float noise=(float)(rng.NextDouble()*2-1);samples[i]=type==0?(noise*.55f+Mathf.Sin(t*2*Mathf.PI*75)*.3f)*Mathf.Exp(-t*24):type==1?noise*.25f*(Mathf.Exp(-t*70)+Mathf.Exp(-Mathf.Abs(t-.23f)*90)):noise*.25f*Mathf.Exp(-t*90);}clip.SetData(samples,0);return clip;}
  void BuildEffects(){if(sound)return;sound=gameObject.AddComponent<AudioSource>();sound.spatialBlend=1;sound.minDistance=2;sound.maxDistance=65;sound.playOnAwake=false;shotClip=Clip("Gun report",.32f,0);reloadClip=Clip("Magazine and bolt",.42f,1);shotClip=HotelAudio.Prefer("gunshot",shotClip);reloadClip=HotelAudio.Prefer("reload",reloadClip);dryClip=Clip("Empty chamber",.1f,2);effectMaterial=new Material(Shader.Find("Universal Render Pipeline/Unlit")??Shader.Find("Unlit/Color"));effectMaterial.color=new Color(1,.72f,.2f);
   flash=GameObject.CreatePrimitive(PrimitiveType.Sphere);flash.name="Muzzle flash";flash.transform.SetParent(transform,false);Destroy(flash.GetComponent<Collider>());flash.transform.localScale=new Vector3(.05f,.05f,.15f);flash.GetComponent<Renderer>().sharedMaterial=effectMaterial;flashLight=flash.AddComponent<Light>();flashLight.color=new Color(1,.64f,.18f);flashLight.range=2;flashLight.intensity=suppressed?.5f:3;flash.SetActive(false);
   traces=new LineRenderer[Mathf.Max(1,pellets)];traceUntil=new float[traces.Length];for(int i=0;i<traces.Length;i++){var go=new GameObject("Shot tracer "+i);go.transform.SetParent(transform,false);var line=go.AddComponent<LineRenderer>();line.sharedMaterial=effectMaterial;line.positionCount=2;line.widthMultiplier=.012f;line.useWorldSpace=true;line.enabled=false;line.shadowCastingMode=UnityEngine.Rendering.ShadowCastingMode.Off;traces[i]=line;}
   shells=Particles("Ejected brass",new Vector3(.03f,.04f,0),.7f,2,.012f,new Color(.7f,.5f,.15f));impacts=Particles("Bullet impact",Vector3.zero,.25f,1.5f,.025f,new Color(1,.64f,.2f));
  }
