  void OnGUI(){if(!user||!user.held||user.held.gameObject!=gameObject||user.GameplayPaused)return;if(ammoStyle==null)ammoStyle=new GUIStyle(GUI.skin.label){fontSize=20,fontStyle=FontStyle.Bold,alignment=TextAnchor.MiddleRight};var old=GUI.color;GUI.color=Color.white;GUI.Label(new Rect(Screen.width-340,Screen.height-136,300,64),GetComponent<HotelItem>().displayName+"\n"+(Reloading?"RELOADING  "+Mathf.RoundToInt(ReloadProgress*100)+"%":Ammo+" / "+Reserve+"    R RELOAD"),ammoStyle);if(Time.time<hitUntil){GUI.color=killed?new Color(1,.25f,.16f):Color.white;float x=Screen.width*.5f,y=Screen.height*.5f;GUI.DrawTexture(new Rect(x-10,y-10,4,4),Texture2D.whiteTexture);GUI.DrawTexture(new Rect(x+6,y-10,4,4),Texture2D.whiteTexture);GUI.DrawTexture(new Rect(x-10,y+6,4,4),Texture2D.whiteTexture);GUI.DrawTexture(new Rect(x+6,y+6,4,4),Texture2D.whiteTexture);}GUI.color=old;}
